  10	static INLINE double min_4(const double *ptr)
  11	{
  12	    double retval = ptr[0];
  13	    int i;
  14	    for (i = 1; i < 4; ++i) {
  15	        if (ptr[i] < retval) {
  16	            retval = ptr[i];
  17	        }
  18	    }
  19	    return retval;
  20	}
  21	
  22	static INLINE double max_4(const double *ptr)
  23	{
  24	    double retval = ptr[0];
  25	    int i;
  26	    for (i = 1; i < 4; ++i) {
  27	        if (ptr[i] > retval) {
  28	            retval = ptr[i];
  29	        }
  30	    }
  31	    return retval;
  32	}
