  39	// Kernel for overlap computation.
  40	static INLINE void _compute_overlap(double *overlap,
  41	                                    double *area_ratio,
  42	                                    double *ilon,
  43	                                    double *ilat,
  44	                                    double *olon,
  45	                                    double *olat)
  46	{
  47	    overlap[0] = computeOverlap(ilon,ilat,olon,olat,0,1,area_ratio);
