  50	#define GETPTR2(x,ncols,i,j) (x + (i) * (ncols) + (j))
  51	#define GETPTRILON(x,i,j) (x + (j))
  52	
  53	void _reproject_slice_c(int startx, int endx, int starty, int endy, int nx_out, int ny_out,
  54	    double *xp_inout, double *yp_inout, double *xw_in, double *yw_in, double *xw_out, double *yw_out,
  55	    double *array, double *array_new, double *weights,
  56	    int col_in, int col_out, int col_array, int col_new)
  57	{
  58	    int i, j, ii, jj, xmin, xmax, ymin, ymax;
  59	    double ilon[4], ilat[4], olon[4], olat[4], minmax_x[4], minmax_y[4];
  60	    double overlap, area_ratio, original;
  61	
  62	    // Main loop.
  63	    for (i = startx; i < endx; ++i) {
  64	        for (j = starty; j < endy; ++j) {
  65	            // For every input pixel we find the position in the output image in
  66	            // pixel coordinates, then use the full range of overlapping output
  67	            // pixels with the exact overlap function.
  68	
  69	            minmax_x[0] = *GETPTR2(xp_inout,col_in,j,i);
  70	            minmax_x[1] = *GETPTR2(xp_inout,col_in,j,i + 1);
  71	            minmax_x[2] = *GETPTR2(xp_inout,col_in,j + 1,i + 1);
  72	            minmax_x[3] = *GETPTR2(xp_inout,col_in,j + 1,i);
  73	
  74	            minmax_y[0] = *GETPTR2(yp_inout,col_in,j,i);
  75	            minmax_y[1] = *GETPTR2(yp_inout,col_in,j,i + 1);
  76	            minmax_y[2] = *GETPTR2(yp_inout,col_in,j + 1,i + 1);
  77	            minmax_y[3] = *GETPTR2(yp_inout,col_in,j + 1,i);
  78	
  79	            xmin = (int)(min_4(minmax_x) + .5);
  80	            xmax = (int)(max_4(minmax_x) + .5);
  81	            ymin = (int)(min_4(minmax_y) + .5);
  82	            ymax = (int)(max_4(minmax_y) + .5);
  83	
  84	            // Fill in ilon/ilat.
  85	            ilon[0] = to_rad(*GETPTR2(xw_in,col_in,j+1,i));
  86	            ilon[1] = to_rad(*GETPTR2(xw_in,col_in,j+1,i+1));
  87	            ilon[2] = to_rad(*GETPTR2(xw_in,col_in,j,i+1));
  88	            ilon[3] = to_rad(*GETPTR2(xw_in,col_in,j,i));
  89	
  90	            ilat[0] = to_rad(*GETPTR2(yw_in,col_in,j+1,i));
  91	            ilat[1] = to_rad(*GETPTR2(yw_in,col_in,j+1,i+1));
  92	            ilat[2] = to_rad(*GETPTR2(yw_in,col_in,j,i+1));
  93	            ilat[3] = to_rad(*GETPTR2(yw_in,col_in,j,i));
  94	
  95	            xmin = xmin > 0 ? xmin : 0;
  96	            xmax = (nx_out-1) < xmax ? (nx_out-1) : xmax;
  97	            ymin = ymin > 0 ? ymin : 0;
  98	            ymax = (ny_out-1) < ymax ? (ny_out-1) : ymax;
  99	
 100	            for (ii = xmin; ii < xmax + 1; ++ii) {
 101	                for (jj = ymin; jj < ymax + 1; ++jj) {
 102	                    // Fill out olon/olat.
 103	                    olon[0] = to_rad(*GETPTR2(xw_out,col_out,jj+1,ii));
 104	                    olon[1] = to_rad(*GETPTR2(xw_out,col_out,jj+1,ii+1));
 105	                    olon[2] = to_rad(*GETPTR2(xw_out,col_out,jj,ii+1));
 106	                    olon[3] = to_rad(*GETPTR2(xw_out,col_out,jj,ii));
 107	
 108	                    olat[0] = to_rad(*GETPTR2(yw_out,col_out,jj+1,ii));
 109	                    olat[1] = to_rad(*GETPTR2(yw_out,col_out,jj+1,ii+1));
 110	                    olat[2] = to_rad(*GETPTR2(yw_out,col_out,jj,ii+1));
 111	                    olat[3] = to_rad(*GETPTR2(yw_out,col_out,jj,ii));
 112	
 113	                    // Compute the overlap.
 114	                    _compute_overlap(&overlap,&area_ratio,ilon,ilat,olon,olat);
 115	                    _compute_overlap(&original,&area_ratio,olon,olat,olon,olat);
 116	
 117	                    // Write into array_new and weights.
 118	                    *GETPTR2(array_new,col_new,jj,ii) += *GETPTR2(array,col_array,j,i) *
 119	                                                                     (overlap / original);
 120	
 121	                    *GETPTR2(weights,col_new,jj,ii) += (overlap / original);
 122	                }
 123	            }
 124	        }
 125	    }
 126	}
