 649	/*
 650	 * Finds the point of intersection p between two closed segments ab and cd.
 651	 *
 652	 * Returns p and a char with the following meaning:
 653	 *
 654	 *   COLINEAR_SEGMENTS: The segments colinearly overlap, sharing a point.
 655	 *
 656	 *   ENDPOINT_ONLY:     An endpoint (vertex) of one segment is on the other
 657	 *                      segment, but COLINEAR_SEGMENTS doesn't hold.
 658	 *
 659	 *   NORMAL_INTERSECT:  The segments intersect properly (i.e., they share
 660	 *                      a point and neither ENDPOINT_ONLY nor
 661	 *                      COLINEAR_SEGMENTS holds).
 662	 *
 663	 *   NO_INTERSECTION:   The segments do not intersect (i.e., they share
 664	 *                      no points).
 665	 *
 666	 * Note that two colinear segments that share just one point, an endpoint
 667	 * of each, returns COLINEAR_SEGMENTS rather than ENDPOINT_ONLY as one
 668	 * might expect.
 669	 */
 670	int SegSegIntersect(Vec *pEdge, Vec *qEdge, Vec *p0, Vec *p1, Vec *q0, Vec *q1,
 671	                    Vec *intersect1, Vec *intersect2) {
 672	  double pDot, qDot;   // Dot product [cos(length)] of the edge vertices
 673	  double p0Dot, p1Dot;  // Dot product from vertices to intersection
 674	  double q0Dot, q1Dot;  // Dot pro}duct from vertices to intersection
 675	  int len;
 676	
 677	  // Get the edge lengths (actually cos(length))
 678	
 679	  pDot = Dot(p0, p1);
 680	  qDot = Dot(q0, q1);
 681	
 682	  // Find the point of intersection
 683	
 684	  len = Cross(pEdge, qEdge, intersect1);
 685	
 686	  // If the two edges are colinear, check to see if they overlap
 687	
 688	  if (len == 0) {
 689	    if (Between(q0, p0, p1) && Between(q1, p0, p1)) {
 690	      intersect1 = q0;
 691	      intersect2 = q1;
 692	      return COLINEAR_SEGMENTS;
 693	    }
 694	
 695	    if (Between(p0, q0, q1) && Between(p1, q0, q1)) {
 696	      intersect1 = p0;
 697	      intersect2 = p1;
 698	      return COLINEAR_SEGMENTS;
 699	    }
 700	
 701	    if (Between(q0, p0, p1) && Between(p1, q0, q1)) {
 702	      intersect1 = q0;
 703	      intersect2 = p1;
 704	      return COLINEAR_SEGMENTS;
 705	    }
 706	
 707	    if (Between(p0, q0, q1) && Between(q1, p0, p1)) {
 708	      intersect1 = p0;
 709	      intersect2 = q1;
 710	      return COLINEAR_SEGMENTS;
 711	    }
 712	
 713	    if (Between(q1, p0, p1) && Between(p1, q0, q1)) {
 714	      intersect1 = p0;
 715	      intersect2 = p1;
 716	      return COLINEAR_SEGMENTS;
 717	    }
 718	
 719	    if (Between(q0, p0, p1) && Between(p0, q0, q1)) {
 720	      intersect1 = p0;
 721	      intersect2 = q0;
 722	      return COLINEAR_SEGMENTS;
 723	    }
 724	
 725	    return NO_INTERSECTION;
 726	  }
 727	
 728	  // If this is the wrong one of the two
 729	  // (other side of the sky) reverse it
 730	
 731	  Normalize(intersect1);
 732	
 733	  if (Dot(intersect1, p0) < 0.)
 734	    Reverse(intersect1);
 735	
 736	  // Point has to be inside both sides to be an intersection
 737	
 738	  if ((p0Dot = Dot(intersect1, p0)) < pDot)
 739	    return NO_INTERSECTION;
 740	  if ((p1Dot = Dot(intersect1, p1)) < pDot)
 741	    return NO_INTERSECTION;
 742	  if ((q0Dot = Dot(intersect1, q0)) < qDot)
 743	    return NO_INTERSECTION;
 744	  if ((q1Dot = Dot(intersect1, q1)) < qDot)
 745	    return NO_INTERSECTION;
 746	
 747	  // Otherwise, if the intersection is at an endpoint
 748	
 749	  if (p0Dot == pDot)
 750	    return ENDPOINT_ONLY;
 751	  if (p1Dot == pDot)
 752	    return ENDPOINT_ONLY;
 753	  if (q0Dot == qDot)
 754	    return ENDPOINT_ONLY;
 755	  if (q1Dot == qDot)
 756	    return ENDPOINT_ONLY;
 757	
 758	  // Otherwise, it is a normal intersection
 759	
 760	  return NORMAL_INTERSECT;
 761	}
