 983	/*
 984	 * Check the vertex list for adjacent pairs of
 985	 * points which are too close together for the
 986	 * subsequent dot- and cross-product calculations
 987	 * of Girard's theorem.
 988	 */
 989	void RemoveDups(int *nv, Vec *V) {
 990	  int i, nvnew;
 991	  Vec Vnew[16];
 992	  Vec tmp;
 993	  double lon, lat;
 994	
 995	  double separation;
 996	
 997	  if (DEBUG >= 4) {
 998	    printf("RemoveDups() TOLERANCE = %13.6e [%13.6e arcsec]\n\n", TOLERANCE,
 999	           TOLERANCE / DEG_TO_RADIANS * 3600.);
1000	
1001	    for (i = 0; i < *nv; ++i) {
1002	      lon = atan2(V[i].y, V[i].x) / DEG_TO_RADIANS;
1003	      lat = asin(V[i].z) / DEG_TO_RADIANS;
1004	
1005	      printf("RemoveDups() orig: %3d [%13.6e,%13.6e,%13.6e] "
1006	             "-> (%10.6f,%10.6f)\n",
1007	             i, V[i].x, V[i].y, V[i].z, lon, lat);
1008	
1009	      fflush(stdout);
1010	    }
1011	
1012	    printf("\n");
1013	  }
1014	
1015	  Vnew[0].x = V[0].x;
1016	  Vnew[0].y = V[0].y;
1017	  Vnew[0].z = V[0].z;
1018	
1019	  nvnew = 0;
1020	
1021	  for (i = 0; i < *nv; ++i) {
1022	    ++nvnew;
1023	
1024	    Vnew[nvnew].x = V[(i + 1) % *nv].x;
1025	    Vnew[nvnew].y = V[(i + 1) % *nv].y;
1026	    Vnew[nvnew].z = V[(i + 1) % *nv].z;
1027	
1028	    Cross(&V[i], &V[(i + 1) % *nv], &tmp);
1029	
1030	    separation = Normalize(&tmp);
1031	
1032	    if (DEBUG >= 4) {
1033	      printf("RemoveDups(): %3d x %3d: distance = %13.6e "
1034	             "[%13.6e arcsec] (would become %d)\n",
1035	             (i + 1) % *nv, i, separation, separation / DEG_TO_RADIANS * 3600.,
1036	             nvnew);
1037	
1038	      fflush(stdout);
1039	    }
1040	
1041	    if (separation < TOLERANCE) {
1042	      --nvnew;
1043	
1044	      if (DEBUG >= 4) {
1045	        printf("RemoveDups(): %3d is a duplicate (nvnew -> %d)\n", i, nvnew);
1046	
1047	        fflush(stdout);
1048	      }
1049	    }
1050	  }
1051	
1052	  if (DEBUG >= 4) {
1053	    printf("\n");
1054	    fflush(stdout);
1055	  }
1056	
1057	  if (nvnew < *nv) {
1058	    for (i = 0; i < nvnew; ++i) {
1059	      V[i].x = Vnew[i].x;
1060	      V[i].y = Vnew[i].y;
1061	      V[i].z = Vnew[i].z;
1062	    }
1063	
1064	    *nv = nvnew;
1065	  }
1066	}
