   656	/*
   657	 * Finds the point of intersection p between two closed segments ab and cd.
   658	 *
   659	 * Returns p and a char with the following meaning:
   660	 *
   661	 *   COLINEAR_SEGMENTS: The segments colinearly overlap, sharing a point.
   662	 *
   663	 *   ENDPOINT_ONLY:     An endpoint (vertex) of one segment is on the other
   664	 *                      segment, but COLINEAR_SEGMENTS doesn't hold.
   665	 *
   666	 *   NORMAL_INTERSECT:  The segments intersect properly (i.e., they share
   667	 *                      a point and neither ENDPOINT_ONLY nor
   668	 *                      COLINEAR_SEGMENTS holds).
   669	 *
   670	 *   NO_INTERSECTION:   The segments do not intersect (i.e., they share
   671	 *                      no points).
   672	 *
   673	 * Note that two colinear segments that share just one point, an endpoint
   674	 * of each, returns COLINEAR_SEGMENTS rather than ENDPOINT_ONLY as one
   675	 * might expect.
   676	 */
   677	int SegSegIntersect(Vec *pEdge, Vec *qEdge, Vec *p0, Vec *p1, Vec *q0, Vec *q1,
   678	                    Vec *intersect1, Vec *intersect2) {
   679	  double pLength2, qLength2;  // Squared chord lengths of the two edges
   680	  double p0Distance2, p1Distance2;  // Squared distances to the intersection
   681	  double q0Distance2, q1Distance2;
   682	  int len;
   683	
   684	  // Get squared chord lengths.  These retain precision when endpoints are
   685	  // too close for their dot product to be distinguishable from one.
   686	
   687	  pLength2 = SquaredDistance(p0, p1);
   688	  qLength2 = SquaredDistance(q0, q1);
   689	
   690	  // Find the point of intersection
   691	
   692	  len = Cross(pEdge, qEdge, intersect1);
   693	
   694	  // If the two edges are colinear, check to see if they overlap
   695	
   696	  if (len == 0) {
   697	    if (Between(q0, p0, p1) && Between(q1, p0, p1)) {
   698	      intersect1 = q0;
   699	      intersect2 = q1;
   700	      return COLINEAR_SEGMENTS;
   701	    }
   702	
   703	    if (Between(p0, q0, q1) && Between(p1, q0, q1)) {
   704	      intersect1 = p0;
   705	      intersect2 = p1;
   706	      return COLINEAR_SEGMENTS;
   707	    }
   708	
   709	    if (Between(q0, p0, p1) && Between(p1, q0, q1)) {
   710	      intersect1 = q0;
   711	      intersect2 = p1;
   712	      return COLINEAR_SEGMENTS;
   713	    }
   714	
   715	    if (Between(p0, q0, q1) && Between(q1, p0, p1)) {
   716	      intersect1 = p0;
   717	      intersect2 = q1;
   718	      return COLINEAR_SEGMENTS;
   719	    }
   720	
   721	    if (Between(q1, p0, p1) && Between(p1, q0, q1)) {
   722	      intersect1 = p0;
   723	      intersect2 = p1;
   724	      return COLINEAR_SEGMENTS;
   725	    }
   726	
   727	    if (Between(q0, p0, p1) && Between(p0, q0, q1)) {
   728	      intersect1 = p0;
   729	      intersect2 = q0;
   730	      return COLINEAR_SEGMENTS;
   731	    }
   732	
   733	    return NO_INTERSECTION;
   734	  }
   735	
   736	  // If this is the wrong one of the two
   737	  // (other side of the sky) reverse it
   738	
   739	  Normalize(intersect1);
   740	
   741	  if (Dot(intersect1, p0) < 0.)
   742	    Reverse(intersect1);
   743	
   744	  // Point has to be inside both sides to be an intersection
   745	
   746	  p0Distance2 = SquaredDistance(intersect1, p0);
   747	  p1Distance2 = SquaredDistance(intersect1, p1);
   748	  q0Distance2 = SquaredDistance(intersect1, q0);
   749	  q1Distance2 = SquaredDistance(intersect1, q1);
   750	
   751	  if (p0Distance2 > pLength2 * (1. + TOLERANCE))
   752	    return NO_INTERSECTION;
   753	  if (p1Distance2 > pLength2 * (1. + TOLERANCE))
   754	    return NO_INTERSECTION;
   755	  if (q0Distance2 > qLength2 * (1. + TOLERANCE))
   756	    return NO_INTERSECTION;
   757	  if (q1Distance2 > qLength2 * (1. + TOLERANCE))
   758	    return NO_INTERSECTION;
   759	
   760	  // Otherwise, if the intersection is at an endpoint
   761	
   762	  if (p0Distance2 <= pLength2 * TOLERANCE)
   763	    return ENDPOINT_ONLY;
   764	  if (p1Distance2 <= pLength2 * TOLERANCE)
   765	    return ENDPOINT_ONLY;
   766	  if (q0Distance2 <= qLength2 * TOLERANCE)
   767	    return ENDPOINT_ONLY;
   768	  if (q1Distance2 <= qLength2 * TOLERANCE)
   769	    return ENDPOINT_ONLY;
   770	
   771	  // Otherwise, it is a normal intersection
   772	
   773	  return NORMAL_INTERSECT;
   774	}
