   812	/*
   813	 * Vector cross product.
   814	 */
   815	int Cross(Vec *v1, Vec *v2, Vec *v3) {
   816	  double crossLength2, scale2;
   817	
   818	  v3->x = v1->y * v2->z - v2->y * v1->z;
   819	  v3->y = -v1->x * v2->z + v2->x * v1->z;
   820	  v3->z = v1->x * v2->y - v2->x * v1->y;
   821	
   822	  crossLength2 = Dot(v3, v3);
   823	  scale2 = Dot(v1, v1) * Dot(v2, v2);
   824	
   825	  if (crossLength2 <= TOLERANCE * TOLERANCE * scale2)
   826	    return 0;
   827	
   828	  return 1;
   829	}
