   842	/*
   843	 * Squared Cartesian chord distance between two unit vectors.  Computing the
   844	 * differences before squaring avoids the cancellation in 2 - 2 a.b for fine
   845	 * angular separations.
   846	 */
   847	double SquaredDistance(Vec *a, Vec *b) {
   848	  double dx, dy, dz;
   849	
   850	  dx = a->x - b->x;
   851	  dy = a->y - b->y;
   852	  dz = a->z - b->z;
   853	
   854	  return dx * dx + dy * dy + dz * dz;
   855	}
