   906	/*
   907	 * Use Girard's theorem to compute the area of a sky polygon.
   908	 */
   909	double Girard(int nv, Vec *V) {
   910	  int i;
   911	  double area, denominator, determinant;
   912	  Vec *a, *b, *c;
   913	
   914	  if (nv < 3)
   915	    return 0.;
   916	
   917	  /*
   918	   * Triangulate the polygon and use the stable solid-angle expression
   919	   *
   920	   *                         det(a, b, c)
   921	   *   E = 2 atan2( ----------------------------------------------- ).
   922	   *                  1 + a.b + b.c + c.a
   923	   *
   924	   * Computing spherical excess by summing the corner angles and subtracting
   925	   * (n - 2) pi loses all precision once the polygon area approaches machine
   926	   * epsilon.  That is common for high-resolution astronomical images.  The
   927	   * determinant form computes the small quantity directly and remains valid
   928	   * for ordinary, larger celestial pixels too.
   929	   */
   930	  area = 0.;
   931	  a = &V[0];
   932	
   933	  for (i = 1; i < nv - 1; ++i) {
   934	    b = &V[i];
   935	    c = &V[i + 1];
   936	
   937	    determinant =
   938	        a->x * (b->y * c->z - b->z * c->y)
   939	        - a->y * (b->x * c->z - b->z * c->x)
   940	        + a->z * (b->x * c->y - b->y * c->x);
   941	    denominator = 1. + Dot(a, b) + Dot(b, c) + Dot(c, a);
   942	    area += 2. * atan2(determinant, denominator);
   943	  }
   944	
   945	  area = fabs(area);
   946	
   947	  if (mNaN(area))
   948	    area = 0.;
   949	
   950	  if (DEBUG >= 4) {
   951	    printf("Stable spherical area: %13.6e [%d]\n", area, nv);
   952	    fflush(stdout);
   953	  }
   954	
   955	  return area;
   956	}
